mapper.insert:
insert into osh_internal_member_follow_record (
    user_id, follow_type, content, next_follow_time, operator_id, create_time, update_time, delete_flag
) values (
    #{userId}, #{followType}, #{content}, str_to_date(#{nextFollowTime}, '%Y-%m-%d %H:%i:%s'),
    #{operatorId}, now(), now(), 0
)

mapper.select:
select u.id as userId, u.username as username, u.email as email, u.avatar as avatar, latest.member_type as memberType, case latest.member_type when 'vip' then 'VIP Member' when 'small_class' then 'Small Class Member' else latest.member_type end as memberTypeName, p.job_status as jobStatus, p.job_status_name as jobStatusName, p.company_name as companyName, p.position_name as positionName, p.city as city, p.salary_before as salaryBefore, p.salary_after as salaryAfter, p.target_salary as targetSalary, case when p.salary_before is not null and p.salary_after is not null then round(p.salary_after - p.salary_before, 2) else null end as salaryIncrease, date_format(p.entry_time, '%Y-%m-%d %H:%i:%s') as entryTime, p.case_eligible as caseEligible, date_format(follow_summary.last_follow_time, '%Y-%m-%d %H:%i:%s') as lastFollowTime, date_format(follow_summary.next_follow_time, '%Y-%m-%d %H:%i:%s') as nextFollowTime from osh_user u inner join ( select mo.user_id, mo.member_type, mo.expire_time from osh_member_order mo inner join ( select user_id, max(id) as max_id from osh_member_order where pay_status = 1 and delete_flag = 0 group by user_id ) latest_order on latest_order.max_id = mo.id ) latest on latest.user_id = u.id left join osh_internal_member_employment_profile p on p.user_id = u.id and p.delete_flag = 0 left join ( select user_id, max(create_time) as last_follow_time, max(next_follow_time) as next_follow_time from osh_internal_member_follow_record where delete_flag = 0 group by user_id ) follow_summary on follow_summary.user_id = u.id where u.delete_flag = 0
and (u.username like concat('%', #{query.keyword}, '%') or u.email like concat('%', #{query.keyword}, '%') or p.company_name like concat('%', #{query.keyword}, '%') or p.position_name like concat('%', #{query.keyword}, '%'))
and p.job_status = #{query.jobStatus}
and p.salary_before is not null and p.salary_after is not null and (p.salary_after - p.salary_before) >= #{query.minSalaryIncrease}
and p.case_eligible = #{query.caseEligible}
order by case when p.case_eligible = 1 then 1 else 0 end desc, p.update_time desc, u.id desc
